from collections import deque

def kahn(graph):
    indegree = {v: 0 for v in graph}
    for u in graph:
        for v in graph[u]:
            indegree[v] += 1                # count the edges that enter v
    ready = deque(v for v in graph if indegree[v] == 0)
    order = []
    while ready:
        u = ready.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1                # u is placed, so one prerequisite is met
            if indegree[v] == 0:
                ready.append(v)
    return order

